\title[Hamiltonian Compression of Cubic Edge-Transitive Graphs]{The Hamiltonian
Compression Factor of Cubic Edge-Transitive Graphs: A Uniform 2-Symmetry Theorem
for M\"obius-Ladder Circulants}

\author{Aristotle}
\date{June 28, 2026}

\begin{document}

\begin{abstract}
We introduce the \emph{Hamiltonian compression factor} $\kk(\Gamma)$ of a graph:
the largest order of a cyclic automorphism group acting on some Hamiltonian cycle
of $\Gamma$ as a rotation. A graph satisfies $\kk(\Gamma) \ge k$ exactly when it
admits a \emph{$k$-symmetric Hamiltonian cycle} --- a Hamiltonian cycle $C$ with
an automorphism $g$ of order $k$ rotating $C$ by $|V(\Gamma)|/k$ positions. The
motivating conjecture asserts that every Hamiltonian connected cubic
edge-transitive graph has $\kk(\Gamma) \ge 2$, verified by exhaustive computation
on all such graphs up to $10{,}000$ vertices. We prove the conjecture on an
infinite explicit subfamily: the M\"obius-ladder cubic circulants $\ML(n)$ on
$\Zn$ with connection set $\{\pm 1, n/2\}$. Our main theorem shows that for every
even $n \ge 4$, $\ML(n)$ admits a $2$-symmetric Hamiltonian cycle, so
$\kk(\ML(n)) \ge 2$. The witness is uniform: the cycle is the canonical traversal
$0,1,\dots,n-1$ and the order-$2$ automorphism is translation by the diameter
$n/2$. We also prove every $\ML(n)$ is cubic, and identify the base cases
$\ML(4) = K_4$ and $\ML(6) = K_{3,3}$. The governing mechanism is
\emph{difference-invariance}: circulant adjacency depends only on $a-b$, so every
translation is an automorphism, and translation by $n/2$ has order exactly $2$
when $n \ge 4$.
\end{abstract}

\maketitle

\section{Introduction}

A \emph{Hamiltonian cycle} in a finite graph $\Gamma = (V,E)$ is a cyclic ordering
of $V$ in which consecutive vertices are adjacent and each vertex appears once.
This paper concerns a structural refinement of existence: \emph{how symmetric can
a Hamiltonian cycle be made?}

Symmetry is measured against the automorphism group $\Aut(\Gamma)$. A Hamiltonian
cycle $C$ is \emph{$k$-symmetric} if some $g \in \Aut(\Gamma)$ of order $k$ maps
$C$ to itself, acting as a rotation by $|V|/k$ positions. The largest such $k$ is
the \emph{Hamiltonian compression factor} $\kk(\Gamma)$: a $k$-symmetric cycle is
determined by a fundamental segment of length $|V|/k$, the rest generated by the
rotation.

The cubic edge-transitive graphs --- $3$-regular graphs whose automorphism group
acts transitively on edges --- form a sparse, classified census. The motivating
conjecture is the following.

\begin{conjecture}[Compression of cubic edge-transitive graphs]
Every Hamiltonian connected cubic edge-transitive graph $\Gamma$ satisfies
$\kk(\Gamma) \ge 2$; equivalently, it admits a $2$-symmetric Hamiltonian cycle.
\end{conjecture}

Exhaustive computation over all Hamiltonian cubic edge-transitive graphs of order
at most $10{,}000$ found $\kk \ge 2$ in every case. We prove the conjecture on an
infinite explicit subfamily and isolate the responsible mechanism.

\section{Definitions}

Throughout, $\Zn$ is the ring of integers modulo $n$.

\begin{definition}[Diameter element]
The \emph{diameter element} is
$\diam(n) := \big(\lfloor n/2 \rfloor \bmod n\big) \in \Zn$. For even $n$,
translation $x \mapsto x + \diam(n)$ is the candidate order-$2$ rotation.
\end{definition}

\begin{definition}[M\"obius-ladder circulant adjacency]
The \emph{M\"obius-ladder adjacency} on $\Zn$ has connection set $\{+1,-1,n/2\}$:
\[
  \MLAdj(n)(a,b) \;:\Longleftrightarrow\;
  a - b = 1 \ \lor\ a - b = -1 \ \lor\ a - b = \diam(n).
\]
The induced graph is $\ML(n)$. The steps $\pm 1$ form the rim ($n$-cycle); the
step $n/2$ forms the rungs (diameters).
\end{definition}

\begin{definition}[$2$-symmetric Hamiltonian cycle]\label{def:tshc}
Given $n$ and an adjacency relation $\mathrm{Adj}$ on $\Zn$, a
\emph{$2$-symmetric Hamiltonian cycle} consists of bijections
$\mathrm{order} : \Zn \to \Zn$ and $\mathrm{auto} : \Zn \to \Zn$ satisfying:
\begin{enumerate}
  \item[(C)] \textbf{consecutive:} $\mathrm{Adj}(\mathrm{order}(i),\mathrm{order}(i+1))$ for all $i$;
  \item[(P)] \textbf{preserves:} $\mathrm{Adj}(a,b) \Rightarrow \mathrm{Adj}(\mathrm{auto}(a),\mathrm{auto}(b))$;
  \item[(I)] \textbf{involutive:} $\mathrm{auto}(\mathrm{auto}(x)) = x$ for all $x$;
  \item[(N)] \textbf{nontrivial:} $\mathrm{auto} \ne \mathrm{id}$;
  \item[(R)] \textbf{rotation:} $\mathrm{auto}(\mathrm{order}(i)) = \mathrm{order}(i + \diam(n))$ for all $i$.
\end{enumerate}
Axioms (I) and (N) force $\mathrm{auto}$ to have order exactly $2$. A graph on $n$
vertices satisfies $\kk(\Gamma) \ge 2$ iff such a structure exists.
\end{definition}

\section{The half-turn automorphism}

\begin{lemma}[Two half-turns cancel]\label{lem:two}
For even $n$, $\;2 \cdot \diam(n) = 0$ in $\Zn$.
\end{lemma}
\begin{proof}
Write $n = 2k$. Then $\lfloor n/2 \rfloor = k$ and
$2\,\diam(n) = (2k \bmod n) = (n \bmod n) = 0$.
\end{proof}

\begin{lemma}[Self-inverse step]\label{lem:neg}
For even $n$, $\;-\diam(n) = \diam(n)$.
\end{lemma}
\begin{proof}
Rearrange $2\,\diam(n) = 0$ (Lemma~\ref{lem:two}). Hence the rung edge is
undirected and $\MLAdj$ is symmetric.
\end{proof}

\begin{lemma}[Nontrivial swap]\label{lem:ne}
For $n \ge 4$, $\;\diam(n) \ne 0$ in $\Zn$.
\end{lemma}
\begin{proof}
$\diam(n) = 0$ would force $n \mid \lfloor n/2 \rfloor$. But for $n \ge 4$,
$1 \le \lfloor n/2 \rfloor < n$, so no such divisibility holds. The bound
$n \ge 4$ is load-bearing for (N).
\end{proof}

\section{Main results}

\begin{theorem}[Uniform 2-symmetry of M\"obius ladders]\label{thm:main}
For every even $n \ge 4$, the M\"obius-ladder circulant $\ML(n)$ admits a
$2$-symmetric Hamiltonian cycle. Hence $\kk(\ML(n)) \ge 2$.
\end{theorem}
\begin{proof}
Take $\mathrm{order} := \mathrm{id}$ (the traversal $0,1,\dots,n-1$) and
$\mathrm{auto}(x) := x + \diam(n)$. We verify Definition~\ref{def:tshc}.
\emph{(C)} $i - (i+1) = -1$ is an allowed difference, so consecutive positions are
adjacent. \emph{(P)} $(a+\diam(n)) - (b+\diam(n)) = a-b$, so any allowed difference
is preserved --- this is difference-invariance. \emph{(I)}
$\mathrm{auto}(\mathrm{auto}(x)) = x + 2\diam(n) = x$ by Lemma~\ref{lem:two}.
\emph{(N)} If $\mathrm{auto} = \mathrm{id}$ then $\diam(n) = 0$, contradicting
Lemma~\ref{lem:ne}. \emph{(R)} $\mathrm{auto}(\mathrm{order}(i)) = i + \diam(n) =
\mathrm{order}(i + \diam(n))$. All axioms hold, uniformly in $n$.
\end{proof}

\begin{theorem}[Cubicity]\label{thm:cubic}
For every even $n \ge 4$ and every $a \in \Zn$,
$\big|\{\, b : \MLAdj(n)(a,b) \,\}\big| = 3$.
\end{theorem}
\begin{proof}
The neighbors of $a$ are $a-1$, $a+1$, and $a+\diam(n)$ (using
Lemma~\ref{lem:neg}). These are pairwise distinct for $n \ge 4$: $a-1 \ne a+1$
since $2 \ne 0$, and $a \pm 1 \ne a + \diam(n)$ since $\diam(n) = n/2 \notin
\{1,-1\}$ for $n \ge 4$. Hence the neighborhood has exactly three elements.
\end{proof}

\section{Base cases: classical cubic edge-transitive graphs}

\begin{proposition}[$\ML(4) = K_4$]\label{prop:k4}
In $\ML(4)$, $\;\MLAdj(4)(a,b) \iff a \ne b$. Thus $\ML(4)$ is the complete graph
$K_4$.
\end{proposition}
\begin{proof}
Finite verification over $(\mathbb{Z}/4\mathbb{Z})^2$: the differences
$\{1,-1,2\}$ are exactly the three nonzero residues, so adjacency is
distinctness. $K_4$ is edge-transitive ($S_4$ acts transitively on edges).
\end{proof}

\begin{proposition}[$\ML(6) = K_{3,3}$]\label{prop:k33}
In $\ML(6)$, $\;\MLAdj(6)(a,b) \iff (a \bmod 2) \ne (b \bmod 2)$. Thus $\ML(6)$ is
the complete bipartite graph $K_{3,3}$ with the even/odd bipartition.
\end{proposition}
\begin{proof}
Finite verification over $(\mathbb{Z}/6\mathbb{Z})^2$: the differences
$\{1,-1,3\} = \{1,5,3\}$ are exactly the odd residues, and a difference is odd iff
the endpoints have opposite parity. The parts $\{0,2,4\}$ and $\{1,3,5\}$ give
$K_{3,3}$, which is edge-transitive.
\end{proof}

\begin{corollary}\label{cor:base}
Instantiating Theorems~\ref{thm:main} and~\ref{thm:cubic}:
\begin{enumerate}
  \item $K_4$ admits a $2$-symmetric Hamiltonian cycle; $\kk(K_4) \ge 2$.
  \item $K_{3,3}$ admits a $2$-symmetric Hamiltonian cycle; $\kk(K_{3,3}) \ge 2$.
  \item $K_4$ and $K_{3,3}$ are $3$-regular.
\end{enumerate}
Thus the conjecture holds on its two smallest cubic edge-transitive members.
\end{corollary}

\section{Algorithms}

\textbf{(A) Half-turn tour synthesis.} For even $n \ge 4$, output the cycle
$[0,1,\dots,n-1]$ and the automorphism $x \mapsto (x + n/2) \bmod n$; $O(n)$ time.

\textbf{(B) Compression-factor certificate verifier.} Given $(n,\mathrm{Adj},
\mathrm{order},\mathrm{auto})$, check (C),(P),(I),(N),(R); $O(n\cdot\deg)$ for
sparse graphs, hence $O(n)$ for $\ML(n)$.

\textbf{(C) Generic circulant 2-symmetry search.} For a symmetric connection set
$S$ with $n$ even, difference-invariance makes (P) automatic; only $1 \in S$ and
$n/2 \ne 0$ need checking. This is the algorithmic content of Conjecture FD1.

\section{Discussion}

The proof of Theorem~\ref{thm:main} uses neither cubicity nor edge-transitivity:
only (i) adjacency is a function of $a-b$, and (ii) $n/2$ is a nonzero element of
order $2$. This is strictly weaker than the conjecture's hypotheses and suggests
the right generality is all even-order circulants containing the step $1$.
Theorem~\ref{thm:cubic} and Section on base cases place the family inside the
conjecture's scope but do not power the bound. The base-case identifications are
finite case analyses; the load-bearing results are
Theorems~\ref{thm:main}--\ref{thm:cubic}, uniform over all even $n \ge 4$.

\section{Future directions}

\begin{conjecture}[FD1: Difference-invariance forces $\kk \ge 2$]
Every symmetric circulant on $\Zn$ ($n$ even) whose connection set contains a
Hamiltonian step admits a $2$-symmetric Hamiltonian cycle, independent of degree.
\end{conjecture}
\begin{conjecture}[FD2: 2-adic valuation]
$\kk(\ML(n)) = 2^{v_2(n)}$, realized by nested rotations $n/2, n/4, \dots$.
\end{conjecture}
\begin{conjecture}[FD3: The mission conjecture]
Every Hamiltonian cubic edge-transitive graph has $\kk \ge 2$.
\end{conjecture}
\begin{conjecture}[FD4: Bipartite doubles]
If $\kk(\Gamma) = k$, then $\kk(\Gamma \times K_2) \ge 2k$.
\end{conjecture}
\begin{conjecture}[FD5]
No Hamiltonian cubic edge-transitive graph is rotation-rigid.
\end{conjecture}

\section{Conclusion}

We proved, uniformly and constructively, that every M\"obius-ladder cubic
circulant $\ML(n)$ with even $n \ge 4$ has $\kk(\ML(n)) \ge 2$, via the half-turn
translation by $n/2$. The base cases $\ML(4) = K_4$ and $\ML(6) = K_{3,3}$ settle
the conjecture on classical cubic edge-transitive graphs. The governing principle,
difference-invariance, points to a broad generalization beyond the cubic
edge-transitive setting.

