from typing import List

def diam(n: int) -> int:
    return (n // 2) % n

def ml_adj(n: int, a: int, b: int) -> bool:
    d = (a - b) % n
    return d == 1 % n or d == (-1) % n or d == diam(n)

def ml4_is_k4() -> bool:
    return all(ml_adj(4, a, b) == (a != b)
               for a in range(4) for b in range(4))

def ml6_is_k33() -> bool:
    return all(ml_adj(6, a, b) == (a % 2 != b % 2)
               for a in range(6) for b in range(6))

def two_symmetric(n: int) -> bool:
    d = diam(n)
    consec = all(ml_adj(n, i % n, (i + 1) % n) for i in range(n))
    edges = [(a, b) for a in range(n) for b in range(n) if ml_adj(n, a, b)]
    pres = all(ml_adj(n, (a + d) % n, (b + d) % n) for a, b in edges)
    invol = all((x + 2 * d) % n == x for x in range(n))
    nontriv = any((x + d) % n != x for x in range(n))
    return consec and pres and invol and nontriv

if __name__ == '__main__':
    print('ML(4) = K4 :', ml4_is_k4())
    print('ML(6) = K33:', ml6_is_k33())
    print('kappa(K4)  >= 2:', two_symmetric(4))
    print('kappa(K33) >= 2:', two_symmetric(6))

