    require n even and n >= 4
    d <- (n // 2) mod n              # diameter step
    order <- [0, 1, ..., n-1]        # canonical Hamiltonian cycle
    auto  <- (x -> (x + d) mod n)    # half-turn automorphism
    return (order, auto)

